function rememberPlayback(el,a){const key='playback:'+a.path;el.addEventListener('loadedmetadata',()=>{el.loop=!!state.preferences?.loopShort&&el.duration<30;if(state.preferences?.rememberPosition){const saved=Number(localStorage.getItem(key)||0);if(saved>0&&saved<el.duration)el.currentTime=saved;}});let last=0;el.addEventListener('timeupdate',()=>{if(state.preferences?.rememberPosition&&Date.now()-last>1000){last=Date.now();localStorage.setItem(key,String(el.currentTime));}});}

