$('renameCancel').onclick=()=>$('renameDialog').close();$('renameSave').onclick=async()=>{const b=$('renameSave');b.disabled=true;try{const row=await api.command('rename',Number($('renameDialog').dataset.id),$('renameName').value);$('renameDialog').close();await stats();await refresh();await showDetail(row);status('文件已重命名');}catch(e){$('renameError').textContent=e.message;}finally{b.disabled=false;}};

$('renameName').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('renameSave').click();}});

$('folderCancel').onclick=()=>$('folderDialog').close();
for(const [button,command] of [['folderRename','renameFolder'],['folderMove','moveFolder'],['folderRelink','relink']])$(button).onclick=async()=>{const source=$('folderDialog').dataset.path;$(button).disabled=true;$('folderError').textContent='';try{const result=await api.command(command,source,...(command==='renameFolder'?[$('folderName').value]:[]));if(result){state.folder=result.path||'';$('folderDialog').close();await stats();await refresh();status('文件夹已更新');}}catch(e){$('folderError').textContent=e.message;}finally{$(button).disabled=false;}};

$('newFolder').onclick=()=>openFolder('', '',true);
$('folderSort').value=localStorage.getItem('folderSort')||'asc';$('folderSort').onchange=()=>{localStorage.setItem('folderSort',$('folderSort').value);renderFolders();};
for(const [button,command] of [['folderCreate','createFolder'],['folderDelete','removeEmptyFolder']])$(button).onclick=async()=>{$(button).disabled=true;$('folderError').textContent='';try{const source=$('folderDialog').dataset.path;const result=await api.command(command,source,...(command==='createFolder'?[$('folderName').value,$('folderDialog').dataset.folderType]:[]));state.folder=result.path||'';$('folderDialog').close();await stats();await refresh();status('文件夹已更新');}catch(e){$('folderError').textContent=e.message;}finally{$(button).disabled=false;}};

let mogrtRequest;
async function sendPremiere(ids){const result=await api.command('pr',ids);if(!result.needsTrackSelection)return result;mogrtRequest=result;$('mogrtSequence').textContent=result.sequence.name;$('mogrtTrack').replaceChildren(...result.sequence.videoTracks.map(t=>{const occupied=t.clips.some(c=>Number(c.end)>Number(result.sequence.position)),o=new Option('V'+(t.index+1)+(occupied?' · 已占用':' · 可插入'),t.index);o.disabled=occupied;return o;}));const free=[...$('mogrtTrack').options].find(o=>!o.disabled);$('mogrtTrack').value=free?.value||'';$('mogrtError').textContent=free?'':'请在 PR 新建一个空视频轨道，再重新发送。';$('mogrtSend').disabled=!free;$('mogrtDialog').showModal();return {message:'请选择 MOGRT 目标轨道'};}
$('mogrtCancel').onclick=()=>$('mogrtDialog').close();$('mogrtSend').onclick=async()=>{$('mogrtSend').disabled=true;$('mogrtError').textContent='';try{const result=await api.command('pr',mogrtRequest.ids,{videoTrack:Number($('mogrtTrack').value),sequenceId:mogrtRequest.sequence.id,position:mogrtRequest.sequence.position});$('mogrtDialog').close();status(result.message);}catch(e){$('mogrtError').textContent=e.message;}finally{$('mogrtSend').disabled=false;}};

async function openAI(embedded=false){if(state.busy)return;if(embedded&&$('preferencesDialog').dataset.aiLoaded==='true')return;const info=await api.command('aiStatus');if(embedded&&!$('preferencesDialog').open)return;$('aiStatus').textContent=(info.installed?'模型已下载':'模型未下载')+' · 已索引 '+info.indexed+' 项';$('aiLabels').value=localStorage.getItem('aiLabels')||info.labels.join('，');$(embedded?'prefPanel-ai':'aiDialog').append($('aiContent'));$('aiClose').hidden=embedded;if(embedded)$('preferencesDialog').dataset.aiLoaded='true';else $('aiDialog').showModal();}
$('aiClose').onclick=()=>$('aiDialog').close();$('aiCancel').onclick=async()=>{await api.command('cancel');$('aiStatus').textContent='正在取消，已完成的结果会保留…';};
for(const [button,command] of [['aiDownload','aiInstall'],['aiBuild','aiIndex'],['aiApply','aiTag']])$(button).onclick=async()=>{if(state.busy)return;if(command==='aiTag'&&!state.selected.size){$('aiStatus').textContent='请先关闭此窗口并选择要加标签的素材';return;}state.busy=true;for(const id of ['aiClose','aiDownload','aiBuild','aiApply','prefSave','prefCancel','prefClose'])$(id).disabled=true;$('aiCancel').disabled=command==='aiInstall';$('aiStatus').textContent='正在处理…';try{const labels=$('aiLabels').value.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);localStorage.setItem('aiLabels',$('aiLabels').value);const result=await api.command(command,...(command==='aiTag'?[[...state.selected],labels]:[]));$('aiStatus').textContent=result.message+(result.errors?.length?' · '+result.errors[0].error:'');await stats();await refresh();}catch(e){$('aiStatus').textContent=e.message;}finally{state.busy=false;for(const id of ['aiClose','aiDownload','aiBuild','aiApply','prefSave','prefCancel','prefClose'])$(id).disabled=false;$('aiCancel').disabled=true;}};
async function applySemanticResult(result){state.semanticIds=result.ids;state.color=null;state.similarTo=null;await refresh();status(result.message);}
$('searchMode').onchange=()=>{state.semanticIds=undefined;$('semanticSearch').hidden=$('searchMode').value!=='semantic';$('search').placeholder=$('searchMode').value==='semantic'?'描述你要找的画面，按 Enter 搜索':'搜索名称、标签、注释  Ctrl+F';run(()=>refresh());};
$('semanticSearch').onclick=()=>run(async()=>{if(state.busy)return;state.busy=true;$('semanticSearch').disabled=true;status('正在按画面描述检索…');try{await applySemanticResult(await api.command('aiSearch',{text:$('search').value}));}finally{state.busy=false;$('semanticSearch').disabled=false;}});
$('search').addEventListener('keydown',e=>{if(e.key==='Enter'&&$('searchMode').value==='semantic'){e.preventDefault();$('semanticSearch').click();}});

for(const button of document.querySelectorAll('[data-menu]'))button.onclick=()=>run(()=>{const r=button.getBoundingClientRect();return api.command('showMenu',button.dataset.menu,{x:r.left,y:r.bottom});});
$('topLeft').onclick=()=>run(()=>action('toggleLeft'));$('topRight').onclick=()=>run(()=>action('toggleRight'));$('pinWindow').onclick=()=>run(async()=>{$('pinWindow').setAttribute('aria-pressed',String(await api.command('pin')));});

$('installFont').onclick=()=>run(async()=>{const button=$('installFont');button.disabled=true;$('detailStatus').textContent='正在安装字体…';try{const result=await api.command('installFont',state.detail.id);$('detailStatus').textContent=result.message;}finally{button.disabled=false;}});

$('themeToggle').onclick=()=>run(async()=>{state.preferences=await api.command('preferences',{theme:document.documentElement.dataset.theme==='dark'?'light':'dark'});applyPreferences();render();});

$('railPreferences').onclick=()=>run(()=>action('preferences'));

$('openSource').onclick=()=>run(async()=>status((await api.command('openSource',state.detail.id)).message));

installMarquee($('viewport'),$('grid'),()=>state.selected,ids=>{state.selected=ids;selection();});

async function quickPreference(patch){try{state.preferences=await api.command('preferences',patch);if(patch.autoPlay===false)for(const card of document.querySelectorAll('.asset'))card.onmouseleave?.();document.querySelectorAll('video,audio').forEach(v=>v.muted=v.tagName==='AUDIO'?!!state.preferences.audioMuted:state.preferences.muted);}finally{applyPreferences();virtualPages?.layoutAll();}}
$('quickNames').onclick=()=>run(async()=>{await appReady;return quickPreference({showNames:!state.preferences.showNames});});

function showSidebarTags(show){document.body.classList.toggle('tags-view',show);$('tagPanel').hidden=!show;document.querySelector('.sidebar').hidden=false;localStorage.setItem('sidebarView',show?'tags':'folders');$('manageTags').setAttribute('aria-pressed',String(show));renderTagList();}
function renderTagList(){const q=$('tagSearch').value.trim().toLocaleLowerCase(),rows=(state.stats?.tagCounts||[]).filter(r=>r.tag.toLocaleLowerCase().includes(q));$('tagList').replaceChildren(...rows.map(row=>{const button=document.createElement('button');button.className='tag-row';button.dataset.tag=row.tag;button.setAttribute('aria-pressed',String($('tag').value===row.tag));const name=document.createElement('span'),count=document.createElement('small');name.textContent=row.tag;count.textContent=row.count;button.append(name,count);button.onclick=()=>run(async()=>{$('tag').value=$('tag').value===row.tag?'':row.tag;await refresh();});return button;}));if(!rows.length){const empty=document.createElement('p');empty.className='tag-empty';empty.textContent=q?'没有匹配的标签':'暂无标签，可在素材详情或批量资料中添加';$('tagList').append(empty);}}
$('tagSearch').oninput=renderTagList;$('editTagsList').onclick=openTags;$('all').onclick=()=>run(async()=>{showSidebarTags(false);await reset();});showSidebarTags(localStorage.getItem('sidebarView')==='tags');

$('filterToggle').onclick=()=>{const panel=$('filterPanel');panel.hidden=!panel.hidden;$('filterToggle').setAttribute('aria-expanded',String(!panel.hidden));if(panel.hidden)$('dateFilters').hidden=true;};

api.onLibraryChanged(()=>run(async()=>{state.stats=await api.command('stats');renderFolders();await refresh(false,true);}));

function appearanceTrigger(value,activate){const icon=window.YimuAppearance.element(value);icon.classList.add('folder-icon');icon.tabIndex=0;icon.setAttribute('role','button');icon.setAttribute('aria-label','设置图标与颜色');icon.title='设置图标与颜色';icon.onclick=e=>{e.stopPropagation();activate();};icon.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();activate();}};return icon;}
function renderFolderTypes(){const A=window.YimuAppearance,used=new Set((state.stats?.folderPreferences||[]).map(f=>f.icon)),dialog=$('folderDialog');const entries=[...Object.entries(A.folderTypes),['',['普通文件夹']]];dialog.dataset.folderType=entries.find(([k])=>!used.has(k))[0];$('folderTypeOptions').replaceChildren();for(const [key,[label]] of entries){const b=document.createElement('button');b.type='button';b.dataset.folderType=key;b.disabled=!!key&&used.has(key);b.title=b.disabled?label+' 已存在':label;b.append(A.element({icon:key||'folder'}));const text=document.createElement('span');text.textContent=label+(b.disabled?'（已有）':'');b.append(text);b.setAttribute('aria-pressed',String(key===dialog.dataset.folderType));b.onclick=()=>{const old=A.folderTypes[dialog.dataset.folderType]?.[0].replace(' / ','')||'新建文件夹';dialog.dataset.folderType=key;if($('folderName').value===old)$('folderName').value=key?label.replace(' / ',''):'新建文件夹';for(const x of $('folderTypeOptions').children)x.setAttribute('aria-pressed',String(x===b));};$('folderTypeOptions').append(b);}}
function editFolderAppearance(folder,name){const value=state.stats.folderPreferences?.find(f=>f.path===folder)||{};window.pickAppearance(name,value,async next=>{await api.command('setFolderAppearance',folder,next);await stats();status('文件夹图标与颜色已保存');},{folder:true,usedTypes:(state.stats.folderPreferences||[]).filter(f=>f.path!==folder).map(f=>f.icon)});}
function editCollectionAppearance(c){window.pickAppearance(c.name,c,async next=>{await api.command('setCollectionAppearance',c.id,next);await stats();status('分类图标与颜色已保存');});}
$('folderAppearance').onclick=()=>editFolderAppearance($('folderDialog').dataset.path,$('folderName').value);
$('collectionAppearance').onclick=()=>editCollectionAppearance(state.stats.collections.find(c=>c.id===collectionEditing));

api.command('appInfo').then(info=>{$('appVersion').textContent='v'+info.version;$('appVersion').title='当前运行版本 '+info.version;}).catch(()=>{$('appVersion').title='版本读取失败';});

function folderBlankContext(e){if(e.target.closest('.folder,select,input,#newFolder,#addFolder'))return;e.preventDefault();run(()=>folderContext());}
$('folders').oncontextmenu=folderBlankContext;document.querySelector('.folder-heading').oncontextmenu=folderBlankContext;
$('viewport').oncontextmenu=e=>{if(e.target.closest('.asset'))return;e.preventDefault();run(()=>folderContext(state.folder));};

for(const id of ['aboutClose','aboutDone'])$(id).onclick=()=>$('aboutDialog').close();
for(const [id,kind,label] of [['aboutCopyOfficial','official','公众号名称'],['aboutCopyWechat','wechat','微信号']])$(id).onclick=async()=>{try{await api.command('copyContact',kind);$('aboutStatus').textContent=label+'已复制';}catch(e){$('aboutStatus').textContent='复制失败：'+e.message;}};

async function openAePreview(id){status('正在读取 AE 合成…');const info=await api.command('aePreviewInfo',id);if(info.missing.length)throw Error('工程缺少素材，请先在 AE 修复：'+info.missing.join(', '));const dialog=$('aePreviewDialog');dialog.dataset.asset=id;$('aePreviewComp').replaceChildren(new Option('请选择成片合成',''),...info.comps.map(c=>new Option(c.name+' · '+c.duration.toFixed(1)+' 秒',c.id)));$('aePreviewComp').value=info.suggested||'';$('aePreviewError').textContent='';dialog.showModal();status('请选择要展示的合成');}
$('aePreviewCancel').onclick=()=>$('aePreviewDialog').close();
$('aePreviewRender').onclick=()=>run(async()=>{const comp=Number($('aePreviewComp').value);if(!comp){$('aePreviewError').textContent='请选择合成';return;}const id=Number($('aePreviewDialog').dataset.asset);$('aePreviewRender').disabled=true;try{status('AE 正在渲染效果预览…');const result=await api.command('aePreview',id,comp);$('aePreviewDialog').close();await refresh();await showDetail(result.asset);status(result.message);}finally{$('aePreviewRender').disabled=false;}});
